workspace_files.schemas/agent_state.proto:
syntax = "proto3";

package agent_org;

// Represents the internal state of a single agent.
// This is the schema-enforced replacement for the free-form Dict[str, Any].
message AgentState {
    // A generic map for simple key-value state. For performance-critical data,
    // prefer strongly-typed fields.
    map<string, Value> kv_store = 1;

    // Example of a strongly-typed field for a numerical agent.
    double numeric_value = 2;

    // Example of a field for vector-based state (e.g., embeddings).
    repeated float vector_state = 3;
}

// A generic value type to allow for some flexibility within the kv_store,
// similar to JSON value types.
message Value {
    oneof kind {
        double double_value = 1;
        string string_value = 2;
        bytes bytes_value = 3;
        int64 int_value = 4;
        bool bool_value = 5;
    }
}
